    @staticmethod
    def _expected_item_map(raw: Any) -> dict[str, dict[str, Any]]:
        if not isinstance(raw, list):
            return {}
        result: dict[str, dict[str, Any]] = {}
        for item in raw:
            if not isinstance(item, Mapping):
                continue
            product_id = str(item.get("product_id") or "").strip()
            if not product_id or product_id in result:
                return {}
            result[product_id] = {
                "quantity": int(item.get("quantity") or 0),
                "selected_spec": str(item.get("selected_spec") or "").strip(),
            }
        return result

    @staticmethod
    def _observed_order_item_map(raw: Any) -> dict[str, dict[str, Any]]:
        if not isinstance(raw, list):
            return {}
        result: dict[str, dict[str, Any]] = {}
        for item in raw:
            if not isinstance(item, Mapping):
                continue
            product = item.get("product") if isinstance(item.get("product"), Mapping) else {}
            product_id = str(product.get("id") or "").strip()
            if not product_id or product_id in result:
                return {}
            result[product_id] = {
                "quantity": int(item.get("quantity") or 0),
                "selected_spec": str(item.get("selectedSpec") or "").strip(),
            }
        return result


